package com.bank.lock.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
public class Account {
    @Id private String id;
    private BigDecimal balance;
    @Version private Long version;

    protected Account() {}
    public String getId() { return id; }
    public void debit(BigDecimal a) { this.balance = balance.subtract(a); }
    public void credit(BigDecimal a) { this.balance = balance.add(a); }
}
