package com.bank.lock.repository;

import com.bank.lock.model.Counter;
import jakarta.persistence.LockModeType;
import jakarta.persistence.QueryHint;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.util.Optional;

public interface CounterRepository extends JpaRepository<Counter, String> {

    // exclusive lock with a 2s wait timeout
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @QueryHints(@QueryHint(name = "jakarta.persistence.lock.timeout", value = "2000"))
    @Query("select c from Counter c where c.name = :name")
    Optional<Counter> findForUpdate(@Param("name") String name);
}
