package com.bank.lock.service;

import com.bank.lock.model.Counter;
import com.bank.lock.repository.CounterRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Slf4j
@Service
@RequiredArgsConstructor
public class SequenceService {
    private final CounterRepository repo;

    // PESSIMISTIC_WRITE guarantees unique, gap-free sequence numbers
    @Transactional
    public long nextChequeNumber() {
        Counter c = repo.findForUpdate("CHEQUE_NO").orElseThrow();  // FOR UPDATE
        long next = c.next();   // serialized — no two callers get the same number
        log.info("Issued cheque number {}", next);
        return next;
    }
}
