package com.bank.lock.service;

import com.bank.lock.model.Account;
import com.bank.lock.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Slf4j
@Service
@RequiredArgsConstructor
public class TransferService {
    private final AccountRepository repo;

    // Lock rows in CONSISTENT ORDER (by id) to avoid deadlock
    @Transactional
    public void transfer(String fromId, String toId, BigDecimal amount) {
        String first = fromId.compareTo(toId) < 0 ? fromId : toId;
        String second = fromId.compareTo(toId) < 0 ? toId : fromId;
        Account a1 = repo.findForUpdate(first).orElseThrow();
        Account a2 = repo.findForUpdate(second).orElseThrow();
        Account from = a1.getId().equals(fromId) ? a1 : a2;
        Account to   = a1.getId().equals(fromId) ? a2 : a1;
        from.debit(amount);
        to.credit(amount);
        log.info("Transferred {} from {} to {}", amount, fromId, toId);
    }
}
